class Solution:
    def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        best = inf
        used = [False] * n

        def dfs(i, total):
            nonlocal best
            if total >= best:
                return
            if i == n:
                best = total
                return
            for j in range(n):
                if not used[j]:
                    used[j] = True
                    dfs(i + 1, total + (nums1[i] ^ nums2[j]))
                    used[j] = False

        dfs(0, 0)
        return best

