class Solution {
public:
    void dfs(vector<int>& a, vector<int>& b, int i, int total, int& best, vector<bool>& used) {
        if (total >= best) return;
        if (i == (int)a.size()) { best = total; return; }
        for (int j = 0; j < (int)b.size(); ++j)
            if (!used[j]) {
                used[j] = true;
                dfs(a, b, i + 1, total + (a[i] ^ b[j]), best, used);
                used[j] = false;
            }
    }
    int minimumXORSum(vector<int>& nums1, vector<int>& nums2) {
        int best = INT_MAX;
        vector<bool> used(nums2.size(), false);
        dfs(nums1, nums2, 0, 0, best, used);
        return best;
    }
};

