class Solution {
    public int minimumXORSum(int[] nums1, int[] nums2) {
        return dfs(nums1, nums2, 0, 0, new boolean[nums2.length], Integer.MAX_VALUE);
    }
    private int dfs(int[] nums1, int[] nums2, int i, int total, boolean[] used, int best) {
        if (total >= best) return best;
        if (i == nums1.length) return total;
        for (int j = 0; j < nums2.length; j++) {
            if (!used[j]) {
                used[j] = true;
                best = dfs(nums1, nums2, i + 1, total + (nums1[i] ^ nums2[j]), used, best);
                used[j] = false;
            }
        }
        return best;
    }
}

