from functools import lru_cache

class Solution:
    def minimumXORSum(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)

        @lru_cache(None)
        def dfs(i, mask):
            if i == n:
                return 0
            return min((nums1[i] ^ nums2[j]) + dfs(i + 1, mask | 1 << j)
                       for j in range(n) if not mask >> j & 1)

        return dfs(0, 0)

