class Solution {
public:
    int minimumXORSum(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        vector<vector<int>> memo(n, vector<int>(1 << n, -1));
        function<int(int, int)> dfs = [&](int i, int mask) -> int {
            if (i == n) return 0;
            int& res = memo[i][mask];
            if (res != -1) return res;
            res = INT_MAX;
            for (int j = 0; j < n; ++j)
                if (!(mask >> j & 1))
                    res = min(res, (nums1[i] ^ nums2[j]) + dfs(i + 1, mask | 1 << j));
            return res;
        };
        return dfs(0, 0);
    }
};

