        const key = i * (1 << n) + mask;
        if (memo.has(key)) return memo.get(key);
        let best = Infinity;
        for (let j = 0; j < n; j++)
            if (!(mask & (1 << j)))
                best = Math.min(best, (nums1[i] ^ nums2[j]) + dfs(i + 1, mask | (1 << j)));
        memo.set(key, best);
        return best;
    };
    return dfs(0, 0);
};

