var minimumXORSum = function(nums1, nums2) {
    const n = nums1.length;
    const size = 1 << n;
    const dp = new Array(size).fill(Infinity);
    dp[0] = 0;
    for (let mask = 1; mask < size; mask++) {
        let pc = 0;
        for (let k = mask; k; k >>= 1) pc += k & 1;
        const i = pc - 1;
        for (let j = 0; j < n; j++)
            if (mask & (1 << j))
                dp[mask] = Math.min(dp[mask], dp[mask ^ (1 << j)] + (nums1[i] ^ nums2[j]));
    }
    return dp[size - 1];
};
